/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `community` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '小区名称',
  `address` varchar(255) DEFAULT NULL COMMENT '小区地址',
  `build_year` varchar(10) DEFAULT NULL COMMENT '建成年份',
  `develop_company` varchar(100) DEFAULT NULL COMMENT '开发企业',
  `property_company` varchar(100) DEFAULT NULL COMMENT '物业服务企业',
  `area` decimal(10,2) DEFAULT '0.00' COMMENT '占地面积(万㎡)',
  `building_area` decimal(10,2) DEFAULT '0.00' COMMENT '建筑面积(万㎡)',
  `green_rate` decimal(5,2) DEFAULT '0.00' COMMENT '绿化率(%)',
  `floor_area_ratio` decimal(5,2) DEFAULT '0.00' COMMENT '容积率',
  `elevators` int DEFAULT '0' COMMENT '电梯数量',
  `parking_spaces` int DEFAULT '0' COMMENT '停车位数量',
  `ebike_shed` int DEFAULT '0' COMMENT '电动车棚数量',
  `ebike_charger` int DEFAULT '0' COMMENT '电动车充电桩数量',
  `fire_station` int DEFAULT '0' COMMENT '微型消防站数量',
  `smoke_detector` int DEFAULT '0' COMMENT '独立烟感数量',
  `fire_hydrant` int DEFAULT '0' COMMENT '消火栓数量',
  `community_committee` varchar(100) DEFAULT NULL COMMENT '社区居委会名称',
  `committee_director` varchar(50) DEFAULT NULL COMMENT '居委会主任',
  `committee_phone` varchar(20) DEFAULT NULL COMMENT '居委会联系电话',
  `party_branch` varchar(100) DEFAULT NULL COMMENT '党支部名称',
  `party_secretary` varchar(50) DEFAULT NULL COMMENT '党支部书记',
  `party_members` int DEFAULT '0' COMMENT '党员人数',
  `property_type` varchar(20) DEFAULT '住宅' COMMENT '物业类型',
  `heating_mode` varchar(20) DEFAULT NULL COMMENT '供暖方式',
  `water_mode` varchar(20) DEFAULT NULL COMMENT '供水方式',
  `electric_mode` varchar(20) DEFAULT NULL COMMENT '供电方式',
  `gas_mode` varchar(20) DEFAULT NULL COMMENT '燃气方式',
  `property_fee` decimal(5,2) DEFAULT '0.00' COMMENT '物业费标准',
  `remark` text COMMENT '备注',
  `buildings` int DEFAULT '0' COMMENT '楼栋数',
  `units` int DEFAULT '0' COMMENT '单元数',
  `total_households` int DEFAULT '0' COMMENT '建筑户数',
  `resident_households` int DEFAULT '0' COMMENT '常住户数',
  `population` int DEFAULT '0' COMMENT '常住人口',
  `representatives` int DEFAULT '0' COMMENT '居民代表人数',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='小区基本信息表';
/*!40101 SET character_set_client = @saved_cs_client */;
