/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `disabled` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '姓名',
  `id_card` varchar(30) DEFAULT '' COMMENT '身份证号',
  `gender` varchar(10) DEFAULT '男' COMMENT '性别',
  `ethnicity` varchar(20) DEFAULT '汉族' COMMENT '民族',
  `education` varchar(20) DEFAULT '' COMMENT '文化程度',
  `marital` varchar(20) DEFAULT '' COMMENT '婚姻状况',
  `household_type` varchar(20) DEFAULT '非农业' COMMENT '户口类型',
  `phone` varchar(30) DEFAULT '' COMMENT '联系电话',
  `street` varchar(50) DEFAULT '寺家庄镇' COMMENT '街道区划',
  `community` varchar(50) DEFAULT '寺家庄社区' COMMENT '社区区划',
  `address` varchar(500) DEFAULT '' COMMENT '居住地址',
  `guardian_name` varchar(50) DEFAULT '' COMMENT '监护人姓名',
  `guardian_relation` varchar(20) DEFAULT '' COMMENT '监护人关系',
  `guardian_phone` varchar(30) DEFAULT '' COMMENT '监护人电话',
  `disability_id` varchar(50) DEFAULT '' COMMENT '残疾证号',
  `disability_type` varchar(20) DEFAULT '' COMMENT '残疾类别',
  `disability_level` varchar(10) DEFAULT '' COMMENT '残疾等级',
  `valid_date` varchar(20) DEFAULT '' COMMENT '有效期开始',
  `status` varchar(20) DEFAULT '持证' COMMENT '持证状态',
  `approve_date` varchar(20) DEFAULT '' COMMENT '批准时间',
  `disability_detail` varchar(200) DEFAULT '' COMMENT '残疾详情',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `idx_disability_type` (`disability_type`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='残疾人登记表';
/*!40101 SET character_set_client = @saved_cs_client */;
