CREATE TABLE `property` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `community` varchar(100) NOT NULL COMMENT '小区名称',
  `company` varchar(200) DEFAULT '' COMMENT '物业企业名称',
  `legal_person` varchar(50) DEFAULT '' COMMENT '法人代表',
  `company_phone` varchar(50) DEFAULT '' COMMENT '企业电话',
  `manager` varchar(50) DEFAULT '' COMMENT '项目负责人',
  `manager_phone` varchar(50) DEFAULT '' COMMENT '负责人电话',
  `address` varchar(300) DEFAULT '' COMMENT '小区地址',
  `build_year` varchar(50) DEFAULT '' COMMENT '建成年份',
  `property_type` varchar(50) DEFAULT '住宅' COMMENT '物业性质',
  `area_residential` decimal(10,4) DEFAULT '0.0000' COMMENT '住宅面积(万㎡)',
  `area_commercial` decimal(10,4) DEFAULT '0.0000' COMMENT '商业面积(万㎡)',
  `buildings_low` varchar(200) DEFAULT '' COMMENT '多层建筑',
  `buildings_high` varchar(200) DEFAULT '' COMMENT '高层建筑',
  `households_residential` int DEFAULT '0' COMMENT '住宅户数',
  `households_commercial` int DEFAULT '0' COMMENT '商业户数',
  `car_parking_ground` int DEFAULT '0' COMMENT '地上车位',
  `car_parking_underground` int DEFAULT '0' COMMENT '地下车位',
  `car_charger_ground` int DEFAULT '0' COMMENT '地上充电桩',
  `car_charger_underground` int DEFAULT '0' COMMENT '地下充电桩',
  `bike_parking_ground` int DEFAULT '0' COMMENT '非机动车地上车位',
  `bike_parking_underground` int DEFAULT '0' COMMENT '非机动车地下车位',
  `ebike_shed` int DEFAULT '0' COMMENT '电动车棚',
  `ebike_charger` int DEFAULT '0' COMMENT '电动车充电头',
  `elevators` int DEFAULT '0' COMMENT '电梯数量',
  `fire_station` int DEFAULT '0' COMMENT '微型消防站',
  `smoke_detector` int DEFAULT '0' COMMENT '独立烟感',
  `fire_hydrant` int DEFAULT '0' COMMENT '消火栓',
  `water_managed` varchar(10) DEFAULT '是' COMMENT '水一管到户',
  `electric_managed` varchar(10) DEFAULT '是' COMMENT '电一管到户',
  `heating_managed` varchar(10) DEFAULT '是' COMMENT '暖一管到户',
  `contract_type` varchar(50) DEFAULT '前期物业' COMMENT '承接方式',
  `remark` text COMMENT '备注',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_community` (`community`)
